<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Color Contrast Checker','description'=>'Check contrast between foreground and background colors and see WCAG-style ratio.','url'=>'https://smarttoolz.in/tools/color-contrast-checker/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">CONTRAST CHECKER</span><h1>Color Contrast Checker</h1><p>Check the contrast ratio between two colors.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Foreground<input id="fg" type="color" value="#111111"></label><label>Background<input id="bg" type="color" value="#ffffff"></label><button id="go" class="tool-btn">Check Contrast</button><p id="out" style="margin-top:15px;font-size:22px;font-weight:800"></p></div></section></main><script>(()=>{const lum=h=>{let a=[0,2,4].map(i=>parseInt(h.slice(1+i,3+i),16)/255).map(x=>x<=.03928?x/12.92:((x+.055)/1.055)**2.4);return .2126*a[0]+.7152*a[1]+.0722*a[2]},o=document.getElementById('out');document.getElementById('go').onclick=()=>{let r=(Math.max(lum(fg.value),lum(bg.value))+.05)/(Math.min(lum(fg.value),lum(bg.value))+.05);o.textContent=`Contrast ratio: ${r.toFixed(2)}:1 — ${r>=7?'Excellent':r>=4.5?'Good':'Low contrast'}`};document.getElementById('go').click()})();</script><?php smarttoolz_tool_page_end(); ?>